sys_variable_value.value:
(function execute(inputs, outputs) {
  var var_name = inputs.var_name;
  if (var_name.length == 0) {
    return;
  }
  var task = inputs.task;
  var var_value = task.variables[var_name];
  if (var_value == undefined || var_value == null) {
    return;
  }
  var_value = var_value.toString();
  
  var var_value_list = var_value.split(',');
  var list_len = var_value_list.length;
  
  var state_map = {};
  state_map['approved'] = '【承認済】';
  state_map['rejected'] = '【否認済】';
  state_map['not_required'] = '【スキップ】';

  var approver_str = inputs.approver_list.toString();
  var approver_list = approver_str.split(',');
  var approver_len = approver_list.length;
  
  var gr = new GlideRecord('sysapproval_approver');
  gr.addQuery('approver', 'IN', approver_str);
  gr.addQuery('sysapproval', task.sys_id);
  gr.orderByDesc('sys_created_on');
  gr.setLimit(approver_len);
  gr.query();
  
  var grUser = new GlideRecord('sys_user');
  
  while(gr.next()) {
    var approver_sysid =gr.getValue('approver');
    var state = gr.getValue('state');
    var time = gr.getDisplayValue('sys_updated_on');
    var updated_userid = gr.getDisplayValue('sys_updated_by');
    var updated_username_k = '';
    if (updated_userid != '' && updated_userid != 'system' ) {

      grUser.initialize();
      grUser.addQuery('user_name', updated_userid);
      grUser.query();
      if (grUser.next()) {
        if (grUser.getValue('sys_id') != approver_sysid) {

          updated_username_k  = grUser.getValue('u_name_name_k');
        }
      }
    }
    
    grUser.initialize();
    grUser.get(approver_sysid);
    var name_k = grUser.getValue('u_name_name_k');
    var new_value = '';
    if (updated_username_k == '') {
      new_value = name_k + '（' + time + ' ' + state_map[state] + '）';
    } else {
      new_value = name_k + '（' + time + ' ' + state_map[state] + '）';
    }
    for (var i = 0; i < list_len; i++) {
      var one_value = var_value_list[i];
      if (one_value.contains(state_map['approved']) || one_value.contains(state_map['rejected']) || one_value.contains(state_map['not_required']) ) {
        continue;
      }
      if (one_value == name_k) {
        var_value_list[i] = new_value;
        break;
      }
    }
  }
  task.variables[var_name] = var_value_list.join(',');
  task[var_name] = var_value_list.join(',');
  task.update();
})(inputs, outputs);

